/* ---------------- func_000287A4 (src/pilot/func_000287A4.c) ---------------- */
/* func_000287A4: draw a subdivided model's polygons (per-poly mode from a packed 3-bit stream). */
#define gte_ldsxy3(r0, r1, r2) __asm__ volatile ( \
    "mtc2 %0, $12;" "mtc2 %2, $14;" "mtc2 %1, $13" : : "r"(r0), "r"(r1), "r"(r2))
#define gte_nclip() __asm__ volatile ("nop;" "nop;" "nclip")
#define gte_stopz(r0) __asm__ volatile ("swc2 $24, 0(%0)" : : "r"(r0) : "memory")
void func_000287A4(MODEL *model)
{
    int opz;
    int *clut;
    int *poly;
    SVECTOR *verts;
    int uv0;
    int uv1;
    int tpage;
    unsigned int modes;
    int i;
    int *scratch;
    unsigned char mode;
    int idx;

    uv1 = uv0 = 0;
    clut = (int *)0x1F8001F0;
    mode = uv1;
    i = 0;
    scratch = (int *)0x1F800000;
    modes = ((unsigned int *)model)[9];
    modes >>= 2;
    poly = (int *)model->poly_block;
    verts = (SVECTOR *)model->vertices;
    for (i = 0; i < model->num_polys; i++) {
        if (mode != 2) {
            uv0 = poly[2];
            uv1 = poly[3];
            tpage = clut[0];
        } else {
            tpage = (((unsigned char *)poly)[1] & 1) + 1;
            tpage = clut[tpage];
        }
        idx = poly[1];
        switch (mode) {
        case 0:
            if (model->shape_flags & 0x42)
                func_00029448(idx, uv0, uv1, verts);
            else
                func_00027A4C(idx, uv0, uv1, verts);
            if (*(int *)model & 0x40000080)
                func_00027E08(poly[0], tpage, 16, scratch);
            else
                func_00027E08(poly[0], tpage, 16, scratch + 1);
            break;
        case 1:
            func_00027A4C(idx, uv0, uv1, verts);
            func_00027E08(poly[0], tpage, 16, scratch + 2);
            break;
        case 2:
            func_00027620(idx, verts);
            func_00028340(tpage, 4, scratch + 2);
            break;
        case 3:
            func_000277D4(idx, uv0, uv1, verts);
            func_00027E08(poly[0], tpage, 4, scratch + 2);
            break;
        case 4:
            func_000277D4(idx, uv0, uv1, verts);
            opz = 0;
            if ((unsigned short)(D_00096938[0].vx + 0xFF) < 0x3FF)
                opz = 1;
            if ((unsigned short)(D_00096938[1].vx + 0xFF) < 0x3FF)
                opz++;
            if ((unsigned short)(D_00096938[2].vx + 0xFF) < 0x3FF)
                opz++;
            if (opz >= 2)
                gte_ldsxy3(D_0009693C[0], D_0009693C[1], D_0009693C[2]);
            else
                gte_ldsxy3(D_0009693C[7], D_0009693C[9], D_0009693C[8]);
            gte_nclip();
            gte_stopz(&opz);
            if (opz >= 0)
                func_00027E08(poly[0], tpage, 4, scratch + 2);
            break;
        default:
            printf("error!! = %d\n", mode);
            break;
        }
        mode = modes & 7;
        modes >>= 3;
        poly = (int *)((char *)poly + D_00089F1C[*(unsigned char *)poly]);
    }
}
#undef gte_ldsxy3
#undef gte_nclip
#undef gte_stopz

/* ---------------- func_00028AF8 (src/pilot/func_00028AF8.c) ---------------- */
/* Clips the screen-space edge a->b against x = -128 / 640 and appends the
   surviving vertices (with interpolated uv) to D_000A1BC8 (count D_00097158) */
void func_00028AF8(int a, int b)
{
    char pad[16];
    SVECTOR d;
    SVECTOR duv;
    int len;
    int t;
    int f;

    if (D_00096948[a].vx < -128 && D_00096948[b].vx < -128)
        return;
    if (D_00096948[a].vx > 640 && D_00096948[b].vx > 640)
        return;

    d.vx = D_00096948[b].vx - D_00096948[a].vx;
    d.vy = D_00096948[b].vy - D_00096948[a].vy;
    len = SquareRoot0(d.vx * d.vx + d.vy * d.vy);
    if (len == 0)
        return;

    duv.vx = D_0009694C[b].u - D_0009694C[a].u;
    duv.vy = D_0009694C[b].v - D_0009694C[a].v;
    SquareRoot0(duv.vx * duv.vx + duv.vy * duv.vy);

    if (D_00096948[a].vx >= -128 && D_00096948[a].vx <= 640) {
        D_000A1BC8[D_00097158].xy = D_00096948[a];
        D_000A1BC8[D_00097158].uv = D_0009694C[a];
        D_00097158++;
    } else {
        if (D_00096948[a].vx < -128) {
            t = -D_00096948[a].vx - 128;
            D_000A1BC8[D_00097158].xy.vx = -128;
        } else {
            t = D_00096948[a].vx - 640;
            D_000A1BC8[D_00097158].xy.vx = 640;
        }
        f = (t << 12) / len;
        D_000A1BC8[D_00097158].xy.vy = (f * d.vy) / 4096 + D_00096948[a].vy;
        D_000A1BC8[D_00097158].uv.u = (f * duv.vx) / 4096 + D_0009694C[a].u;
        D_000A1BC8[D_00097158].uv.v = (f * duv.vy) / 4096 + D_0009694C[a].v;
        D_00097158++;
    }

    if (D_00096948[b].vx >= -128 && D_00096948[b].vx <= 640)
        return;

    if (D_00096948[b].vx < -128) {
        t = -D_00096948[b].vx - 128;
        D_000A1BC8[D_00097158].xy.vx = -128;
    } else {
        t = D_00096948[b].vx - 640;
        D_000A1BC8[D_00097158].xy.vx = 640;
    }
    f = -((t << 12) / len);
    D_000A1BC8[D_00097158].xy.vy = (f * d.vy) / 4096 + D_00096948[b].vy;
    D_000A1BC8[D_00097158].uv.u = (f * duv.vx) / 4096 + D_0009694C[b].u;
    D_000A1BC8[D_00097158].uv.v = (f * duv.vy) / 4096 + D_0009694C[b].v;
    D_00097158++;
}

